class Solution {
public:
    int countSpecialIntegers(vector<int>& nums) {
        unordered_map<int, vector<int>> info;
        for (int i = 0; i < (int)nums.size(); ++i) {
            vector<int>& v = info[nums[i]];
            if (v.empty()) v = {i, 0, 1, 1};
            else {
                int gap = i - v[0];
                if (v[2] == 1) v[1] = gap;
                else if (gap != v[1]) v[3] = 0;
                v[0] = i;
                ++v[2];
            }
        }
        int ans = 0;
        for (const auto& e : info) if (e.second[2] >= 3 && e.second[3]) ++ans;
        return ans;
    }
};
